import pytest
from sqlmodel import SQLModel, Session, create_engine, select
import workout_app as app

@pytest.fixture
def engine():
    engine = create_engine("sqlite://")
    SQLModel.metadata.create_all(engine)
    yield engine
    engine.dispose()

@pytest.fixture
def session(engine):
    with Session(engine) as session:
        yield session

from pydantic import ValidationError

def test_only_workout_is_a_table():
    assert set(SQLModel.metadata.tables) == {"workout"}
    assert issubclass(app.WorkoutCreate, app.WorkoutBase)
    assert issubclass(app.WorkoutRead, app.WorkoutBase)

def test_create_has_no_id():
    row = app.WorkoutCreate(name="Leg Day")
    assert row.model_dump() == {"name": "Leg Day", "description": ""}
    assert "id" not in app.WorkoutCreate.model_fields

def test_read_requires_id():
    with pytest.raises(ValidationError):
        app.WorkoutRead(name="A")
    assert app.WorkoutRead(id=7, name="A").id == 7

def test_name_validation():
    for schema in (app.WorkoutCreate, app.WorkoutRead):
        with pytest.raises(ValidationError):
            schema(id=1, name="")
    with pytest.raises(ValidationError):
        app.WorkoutUpdate(name="")

def test_patch_omitted_and_null():
    assert app.WorkoutUpdate().name is None and app.WorkoutUpdate().description is None
    assert app.WorkoutUpdate().model_dump(exclude_unset=True) == {}
    assert app.WorkoutUpdate(name=None).model_dump(exclude_unset=True) == {"name": None}
    assert app.WorkoutUpdate(description=None).model_dump(exclude_unset=True) == {"description": None}
    assert app.WorkoutUpdate(name="A").model_dump(exclude_unset=True) == {"name": "A"}

def test_nested_serialization():
    row = app.WorkoutWithExercises(id=1, name="Upper", exercises=[{"id": 2, "name": "Bench"}])
    assert isinstance(row.exercises[0], app.ExerciseRead)
    assert row.model_dump()["exercises"] == [{"id": 2, "name": "Bench"}]

def test_nested_default_is_independent():
    first = app.WorkoutWithExercises(id=1, name="A")
    second = app.WorkoutWithExercises(id=2, name="B")
    first.exercises.append(app.ExerciseRead(id=1, name="Squat"))
    assert second.exercises == []
'''[1:]
_SM_IDS = ['test_only_workout_is_a_table', 'test_create_has_no_id', 'test_read_requires_id', 'test_name_validation', 'test_patch_omitted_and_null', 'test_nested_serialization', 'test_nested_default_is_independent']


import json as _json
from pathlib import Path as _Path
import os as _os
import subprocess as _subprocess
import sys as _sys
import tempfile as _tempfile
import xml.etree.ElementTree as _xml

_SM_RESULTS = None


def _sm_run_tests():
    source = _Path(__file__).read_text().split('# === SUPPLIED SQLMODEL TESTS ===', 1)[0]
    with _tempfile.TemporaryDirectory(prefix='sqlmodel-tests-') as folder:
        work = _Path(folder)
        (work / 'workout_app.py').write_text(source)
        (work / 'test_workout.py').write_text(_SM_TESTS)
        report = work / 'results.xml'
        env = dict(_os.environ)
        for key in ('PYTEST_ADDOPTS', 'PYTEST_PLUGINS', 'PYTHONPATH'):
            env.pop(key, None)
        env['PYTEST_DISABLE_PLUGIN_AUTOLOAD'] = '1'
        try:
            done = _subprocess.run(
                [_sys.executable, '-m', 'pytest', '-c', '/dev/null', '-p', 'no:cacheprovider',
                 '-q', '--tb=short', '--junitxml=' + str(report), str(work / 'test_workout.py')],
                cwd=work, env=env, capture_output=True, text=True, timeout=20)
            if report.exists():
                results = {}
                for case in _xml.parse(report).iter('testcase'):
                    name = case.get('name')
                    failures = [child for child in case if child.tag in ('failure', 'error', 'skipped')]
                    results[name] = ('FAILED ' + name + ' | ' +
                                     (failures[0].text or failures[0].get('message', 'test did not pass'))[-1800:]
                                     if failures else 'passed')
                if set(results) == set(_SM_IDS) and done.returncode in (0, 1):
                    return {key: value.replace('\n', ' | ') for key, value in results.items()}
            error = (done.stdout + done.stderr)[-2200:].replace('\n', ' | ')
        except _subprocess.TimeoutExpired:
            error = 'pytest exceeded 20 seconds'
        except Exception as exc:
            error = str(exc).replace('\n', ' | ')
        return {name: 'FAILED ' + name + ' | ' + error for name in _SM_IDS}


class Solution:
    def run(self, payload: str) -> str:
        global _SM_RESULTS
        target = _json.loads(payload)['test']
        if target == '--list':
            return _json.dumps(_SM_IDS)
        if target not in _SM_IDS:
            return 'Unknown test: ' + str(target)
        if _SM_RESULTS is None:
            _SM_RESULTS = _sm_run_tests()
        return _SM_RESULTS[target]
